  model(subdivPlane)
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}


// === Tab: irradiance ===
const irradianceVert = `
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec2 vTexCoord;

void main(void) {
  vec4 objSpacePosition = vec4(aPosition, 1.0);
  vec4 worldSpacePosition = uModelViewMatrix * objSpacePosition;
  gl_Position = uProjectionMatrix * worldSpacePosition;
  vTexCoord = aTexCoord;
}
`

const irradianceFrag = `
precision mediump float;
varying vec2 vTexCoord;

uniform sampler2D environmentMap;

const float PI = ${Math.PI.toFixed(8)};
const float sampleDelta = 0.1;

float map(float val, float inA, float inB, float outA, float outB) {
  return (val - inA) / (inB - inA) * (outB - outA) + outA;
}

vec3 uvToNormal(vec2 uv) {
  float theta = map(uv.x, 0., 1., 0., PI);
  float phi = map(uv.y, 1., 0., 0., PI);
  return vec3(
    sin(phi) * cos(theta),
    cos(phi),
    sin(phi) * sin(theta)
  );
}

vec4 sampleBackground(vec3 normal) {
  // x = rho sin(phi) cos(theta)
  // y = rho cos(phi)
  // z = rho sin(phi) sin(theta)
  // rho = 1 after normalization
  float phi = acos(normal.y);
  float sinPhi = sin(phi);
  float theta =
    abs(sinPhi) > 0.0001
      ? acos(normal.x / sinPhi)
      : 0.;
  vec2 coord = vec2(
    map(theta, 0., PI, 0., 1.),
    map(phi, 0., PI, 1., 0.)
  );
  return texture2D(environmentMap, coord);
}

vec3 remapColor(vec3 color) {
  // Decrease shadows
  float factor = 8.;
  color = vec3(
    pow(color.r, factor),
    pow(color.g, factor),
    pow(color.b, factor)
  );

  // Increase exposure
  color = 500. * color;

  color = color / (color + vec3(1.0));
  color = pow(color, vec3(1.0/2.2));
  return color;
}

void main() {
  vec3 irradiance = vec3(0.0);  

  vec3 normal = uvToNormal(vTexCoord);
  vec3 up = vec3(0.0, 1.0, 0.0);
  vec3 right = normalize(cross(up, normal));
  up = normalize(cross(normal, right));

  float nrSamples = 0.0;
  for(float phi = 0.0; phi < 2.0 * PI; phi += sampleDelta) {
    for(float theta = 0.0; theta < 0.5 * PI; theta += sampleDelta) {
      // spherical to cartesian (in tangent space)
      vec3 tangentSample = vec3(sin(theta) * cos(phi),  sin(theta) * sin(phi), cos(theta));
      // tangent space to world
      vec3 sampleVec = tangentSample.x * right + tangentSample.y * up + tangentSample.z * normal; 

      irradiance += remapColor(sampleBackground(
        normalize(sampleVec)
      ).rgb) * cos(theta) * sin(theta);
      nrSamples++;
    }
  }
  irradiance = PI * irradiance * (1.0 / float(nrSamples));
  gl_FragColor = vec4(irradiance, 1.0);
}
`

// === Tab: subdivPlane ===

const makePlane = (detail) => {
  return new p5.Geometry(detail, detail, function() {
    this.gid = `subdivPlane|${detail}`;

    const [uVec, vVec] = [createVector(1, 0, 0), createVector(0, 1, 0)];
    const normal = uVec.cross(vVec);

    // This will be the index of the first vertex
    // of this face
    const vertexOffset = this.vertices.length;

    for (let i = 0; i < detail; i++) {
      for (let j = 0; j < detail; j++) {
        const u = i / (detail - 1);
        const v = j / (detail - 1);
        this.vertices.push(
          createVector(0, 0, 0)
          .add(uVec.copy().mult(u - 0.5))
          .add(vVec.copy().mult(v - 0.5))
        );
        this.uvs.push([u, v]);
        this.vertexNormals.push(normal);
      }
    }

    for (let i = 1; i < detail; i++) {
      for (let j = 1; j < detail; j++) {
        // +--+
        //  \ |
        //    +
        this.faces.push([
          vertexOffset + (j - 1) * detail + i - 1,
          vertexOffset + (j - 1) * detail + i,
          vertexOffset + j * detail + i,
        ]);

        // +
        // | \
        // +--+
        this.faces.push([
          vertexOffset + j * detail + i,
          vertexOffset + j * detail + i - 1,
          vertexOffset + (j - 1) * detail + i - 1,
        ]);
      }
    }
  });
}

